package esercizio_riepilogo_classString;

public class escape_sequences {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		/*
		 * Escape Sequences
           Crea Stringhe con ", \', \\, \t e \n.
           Stampa per verificare: es. String frase = "Mario disse: \"Ciao!\"";.
		 */
		
		String frase = "Mario disse: \"Ciao!\"";
		String s1 = "\"";
		String s2 = "\'";
		String s3 = "\\";
		String s4 = "\t";
		String s5 = "\n";
		
		System.out.println(s1 + " prova");
		System.out.println(s2 + " prova");
		System.out.println(s3 + " prova");
		System.out.println(s4 + " prova");
		System.out.println(s5 + " prova");
		System.out.println(frase);
		
		
		
	}

}
